CREATE DATABASE IF NOT EXISTS pharmacy CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE pharmacy;

CREATE TABLE roles (id TINYINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(30) NOT NULL UNIQUE);
INSERT IGNORE INTO roles (id,name) VALUES (1,'Administrator'),(2,'Manager'),(3,'Staff');
CREATE TABLE permissions (id SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(100) NOT NULL UNIQUE, module_name VARCHAR(40) NOT NULL, label VARCHAR(100) NOT NULL);
INSERT IGNORE INTO permissions(code,module_name,label) VALUES
('dashboard.view','Dashboard','View dashboard'),('products.view','Products','View products'),('products.create','Products','Create products'),('products.edit','Products','Edit product details and prices'),('products.delete','Products','Delete products'),('inventory.view','Inventory','View inventory'),('inventory.adjust','Inventory','Adjust stock'),('orders.view','Orders','View orders'),('orders.process','Orders','Process orders'),('orders.confirm','Orders','Confirm orders'),('pos.access','POS','Access POS'),('proformas.create','POS','Create proformas'),('finance.view','Finance','View finance'),('finance.approve','Finance','Approve payments'),('finance.reject','Finance','Reject payments'),('finance.expense','Finance','Record expenses'),('suppliers.view','Suppliers','View suppliers'),('restocks.create','Restocking','Create restocks'),('reports.view','Reports','View reports'),('users.view','Users','View users'),('users.audit','Users','View user activity logs'),('users.manage','Users','Manage users'),('settings.manage','Settings','Manage settings'),('branches.manage','Branches','Manage active branch details'),('branches.view','Branches','View branch details');
CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, role_id TINYINT UNSIGNED NOT NULL, full_name VARCHAR(160) NOT NULL, email VARCHAR(190) NULL UNIQUE, phone VARCHAR(40) NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, staff_position VARCHAR(100) NULL, status ENUM('active','suspended','inactive') NOT NULL DEFAULT 'active', must_change_password BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(role_id) REFERENCES roles(id));
CREATE TABLE branches (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(160) NOT NULL UNIQUE, location VARCHAR(240) NULL, address TEXT NULL, phone VARCHAR(50) NULL, contact_email VARCHAR(190) NULL, finance_email VARCHAR(190) NULL, map_link VARCHAR(1000) NULL, social_whatsapp VARCHAR(80) NULL, social_instagram VARCHAR(500) NULL, payment_instructions TEXT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE user_branches (user_id BIGINT UNSIGNED NOT NULL, branch_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY(user_id,branch_id), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(branch_id) REFERENCES branches(id) ON DELETE CASCADE);
CREATE TABLE user_permissions (user_id BIGINT UNSIGNED NOT NULL, permission_id SMALLINT UNSIGNED NOT NULL, PRIMARY KEY(user_id,permission_id), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(permission_id) REFERENCES permissions(id) ON DELETE CASCADE);
CREATE TABLE login_attempts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, identifier VARCHAR(190) NOT NULL, succeeded BOOLEAN NOT NULL, ip_address VARCHAR(45) NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX(identifier,created_at));
CREATE TABLE audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, actor_id BIGINT UNSIGNED NULL, action VARCHAR(100) NOT NULL, entity_type VARCHAR(80) NOT NULL, entity_id BIGINT UNSIGNED NULL, details JSON NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX(entity_type,entity_id), FOREIGN KEY(actor_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE product_categories (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL UNIQUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE products (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, category_id BIGINT UNSIGNED NULL, code VARCHAR(80) NOT NULL UNIQUE, name VARCHAR(180) NOT NULL, description TEXT NULL, units_per_box INT UNSIGNED NOT NULL DEFAULT 1, allow_individual BOOLEAN NOT NULL DEFAULT FALSE, box_price DECIMAL(14,2) NOT NULL DEFAULT 0, cost_price DECIMAL(14,2) NOT NULL DEFAULT 0, reorder_level_units INT UNSIGNED NOT NULL DEFAULT 0, is_public BOOLEAN NOT NULL DEFAULT FALSE, is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(category_id) REFERENCES product_categories(id) ON DELETE SET NULL, INDEX(is_public,is_active), INDEX(name));
CREATE TABLE suppliers (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(180) NOT NULL, phone VARCHAR(40) NULL, email VARCHAR(190) NULL, address TEXT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE inventory (product_id BIGINT UNSIGNED PRIMARY KEY, stock_units BIGINT UNSIGNED NOT NULL DEFAULT 0, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE branch_inventory (branch_id BIGINT UNSIGNED NOT NULL, product_id BIGINT UNSIGNED NOT NULL, stock_units BIGINT UNSIGNED NOT NULL DEFAULT 0, box_price DECIMAL(14,2) NULL, cost_price DECIMAL(14,2) NULL, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, PRIMARY KEY(branch_id,product_id), FOREIGN KEY(branch_id) REFERENCES branches(id), FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE stock_movements (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, product_id BIGINT UNSIGNED NOT NULL, movement_type ENUM('opening','restock','sale','adjustment','reservation','release') NOT NULL, reference_type VARCHAR(40) NULL, reference_id BIGINT UNSIGNED NULL, quantity_before BIGINT UNSIGNED NOT NULL, quantity_in BIGINT UNSIGNED NOT NULL DEFAULT 0, quantity_out BIGINT UNSIGNED NOT NULL DEFAULT 0, quantity_after BIGINT UNSIGNED NOT NULL, units_per_box_snapshot INT UNSIGNED NOT NULL, performed_by BIGINT UNSIGNED NULL, branch_id BIGINT UNSIGNED NULL, notes VARCHAR(500) NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(product_id) REFERENCES products(id), FOREIGN KEY(performed_by) REFERENCES users(id) ON DELETE SET NULL, FOREIGN KEY(branch_id) REFERENCES branches(id), INDEX(product_id,created_at));
CREATE TABLE restocks (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, branch_id BIGINT UNSIGNED NULL, restock_reference VARCHAR(50) NOT NULL UNIQUE, supplier_id BIGINT UNSIGNED NULL, supplier_invoice_reference VARCHAR(100) NULL, performed_by BIGINT UNSIGNED NULL, restock_date DATE NOT NULL, total_amount DECIMAL(14,2) NOT NULL DEFAULT 0, payment_status ENUM('unpaid','partial','paid') NOT NULL DEFAULT 'unpaid', notes TEXT NULL, status ENUM('draft','confirmed','cancelled') NOT NULL DEFAULT 'draft', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(branch_id) REFERENCES branches(id), FOREIGN KEY(supplier_id) REFERENCES suppliers(id) ON DELETE SET NULL, FOREIGN KEY(performed_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE restock_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, restock_id BIGINT UNSIGNED NOT NULL, product_id BIGINT UNSIGNED NOT NULL, incoming_boxes INT UNSIGNED NOT NULL DEFAULT 0, incoming_loose_units INT UNSIGNED NOT NULL DEFAULT 0, incoming_stock_units BIGINT UNSIGNED NOT NULL, units_per_box_snapshot INT UNSIGNED NOT NULL, previous_cost_price DECIMAL(14,2) NOT NULL, new_cost_price DECIMAL(14,2) NOT NULL, previous_selling_price DECIMAL(14,2) NOT NULL, new_selling_price DECIMAL(14,2) NOT NULL, batch_number VARCHAR(100) NULL, expiry_date DATE NULL, purchase_total DECIMAL(14,2) NOT NULL, FOREIGN KEY(restock_id) REFERENCES restocks(id), FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE customers (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, full_name VARCHAR(160) NOT NULL, email VARCHAR(190) NULL UNIQUE, phone VARCHAR(40) NULL UNIQUE, password_hash VARCHAR(255) NULL, status ENUM('active','inactive') NOT NULL DEFAULT 'active', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE customer_addresses (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, customer_id BIGINT UNSIGNED NOT NULL, label VARCHAR(80) NULL, address TEXT NOT NULL, is_default BOOLEAN NOT NULL DEFAULT FALSE, FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE CASCADE);
CREATE TABLE orders (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_reference VARCHAR(50) NOT NULL UNIQUE, customer_id BIGINT UNSIGNED NOT NULL, branch_id BIGINT UNSIGNED NULL, status ENUM('submitted','processing','partially_confirmed','confirmed','rejected','cancelled','fulfilled') NOT NULL DEFAULT 'submitted', payment_status ENUM('unpaid','paid') NOT NULL DEFAULT 'unpaid', paid_at DATETIME NULL, paid_by BIGINT UNSIGNED NULL, subtotal DECIMAL(14,2) NOT NULL DEFAULT 0, notes TEXT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(customer_id) REFERENCES customers(id), FOREIGN KEY(branch_id) REFERENCES branches(id), FOREIGN KEY(paid_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE order_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_id BIGINT UNSIGNED NOT NULL, product_id BIGINT UNSIGNED NULL, product_name_snapshot VARCHAR(180) NOT NULL, product_code_snapshot VARCHAR(80) NOT NULL, requested_boxes INT UNSIGNED NOT NULL, confirmed_boxes INT UNSIGNED NOT NULL DEFAULT 0, box_price_snapshot DECIMAL(14,2) NULL, line_total DECIMAL(14,2) NULL, FOREIGN KEY(order_id) REFERENCES orders(id), FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE customer_order_payments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_id BIGINT UNSIGNED NOT NULL UNIQUE, amount DECIMAL(14,2) NOT NULL, payment_method VARCHAR(40) NOT NULL, transaction_reference VARCHAR(120) NULL, recorded_by BIGINT UNSIGNED NOT NULL, paid_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(order_id) REFERENCES orders(id), FOREIGN KEY(recorded_by) REFERENCES users(id));
CREATE TABLE customer_order_payment_submissions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_id BIGINT UNSIGNED NOT NULL, branch_id BIGINT UNSIGNED NOT NULL, customer_id BIGINT UNSIGNED NOT NULL, payment_method ENUM('cash_at_branch','bank_transfer','mobile_money','other') NOT NULL, transaction_reference VARCHAR(120) NULL, evidence_path VARCHAR(255) NULL, status ENUM('pending','approved','rejected') NOT NULL DEFAULT 'pending', reviewed_by BIGINT UNSIGNED NULL, reviewed_at DATETIME NULL, rejection_reason VARCHAR(500) NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(order_id) REFERENCES orders(id), FOREIGN KEY(branch_id) REFERENCES branches(id), FOREIGN KEY(customer_id) REFERENCES customers(id), FOREIGN KEY(reviewed_by) REFERENCES users(id) ON DELETE SET NULL, INDEX(branch_id,status));
CREATE TABLE order_invoices (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_id BIGINT UNSIGNED NOT NULL UNIQUE, invoice_reference VARCHAR(50) NOT NULL UNIQUE, total DECIMAL(14,2) NOT NULL, created_by BIGINT UNSIGNED NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(order_id) REFERENCES orders(id), FOREIGN KEY(created_by) REFERENCES users(id));
CREATE TABLE proforma_invoices (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, proforma_reference VARCHAR(50) NOT NULL UNIQUE, cashier_id BIGINT UNSIGNED NOT NULL, customer_id BIGINT UNSIGNED NULL, branch_id BIGINT UNSIGNED NULL, subtotal DECIMAL(14,2) NOT NULL, discount DECIMAL(14,2) NOT NULL DEFAULT 0, tax DECIMAL(14,2) NOT NULL DEFAULT 0, grand_total DECIMAL(14,2) NOT NULL, status ENUM('pending_payment','payment_submitted','approved','rejected','expired','cancelled') NOT NULL DEFAULT 'pending_payment', expires_at DATETIME NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(cashier_id) REFERENCES users(id), FOREIGN KEY(branch_id) REFERENCES branches(id), FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE SET NULL);
CREATE TABLE proforma_invoice_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, proforma_id BIGINT UNSIGNED NOT NULL, product_id BIGINT UNSIGNED NOT NULL, product_name_snapshot VARCHAR(180) NOT NULL, product_code_snapshot VARCHAR(80) NOT NULL, selling_unit ENUM('box','item') NOT NULL, quantity INT UNSIGNED NOT NULL, items_per_box_snapshot INT UNSIGNED NOT NULL, unit_price_snapshot DECIMAL(14,2) NOT NULL, line_total DECIMAL(14,2) NOT NULL, FOREIGN KEY(proforma_id) REFERENCES proforma_invoices(id), FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE payments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, payment_reference VARCHAR(50) NOT NULL UNIQUE, proforma_id BIGINT UNSIGNED NOT NULL, amount DECIMAL(14,2) NOT NULL, payment_method VARCHAR(40) NOT NULL, transaction_reference VARCHAR(120) NULL, verification_status ENUM('pending','approved','rejected') NOT NULL DEFAULT 'pending', evidence_path VARCHAR(255) NULL, rejection_reason VARCHAR(500) NULL, submitted_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, reviewed_by BIGINT UNSIGNED NULL, reviewed_at DATETIME NULL, FOREIGN KEY(proforma_id) REFERENCES proforma_invoices(id), FOREIGN KEY(reviewed_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE sales (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, sale_reference VARCHAR(50) NOT NULL UNIQUE, proforma_id BIGINT UNSIGNED NOT NULL UNIQUE, customer_id BIGINT UNSIGNED NULL, total DECIMAL(14,2) NOT NULL, finalized_by BIGINT UNSIGNED NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(proforma_id) REFERENCES proforma_invoices(id), FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE SET NULL, FOREIGN KEY(finalized_by) REFERENCES users(id));
CREATE TABLE sale_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, sale_id BIGINT UNSIGNED NOT NULL, product_id BIGINT UNSIGNED NOT NULL, product_name_snapshot VARCHAR(180) NOT NULL, quantity_units BIGINT UNSIGNED NOT NULL, unit_price_snapshot DECIMAL(14,2) NOT NULL, line_total DECIMAL(14,2) NOT NULL, FOREIGN KEY(sale_id) REFERENCES sales(id), FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE invoices (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, invoice_reference VARCHAR(50) NOT NULL UNIQUE, sale_id BIGINT UNSIGNED NOT NULL UNIQUE, customer_id BIGINT UNSIGNED NULL, total DECIMAL(14,2) NOT NULL, invoice_status ENUM('issued','void') NOT NULL DEFAULT 'issued', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(sale_id) REFERENCES sales(id), FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE SET NULL);
CREATE TABLE expenses (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, branch_id BIGINT UNSIGNED NULL, expense_reference VARCHAR(50) NOT NULL UNIQUE, category VARCHAR(100) NOT NULL, description VARCHAR(500) NOT NULL, amount DECIMAL(14,2) NOT NULL, expense_date DATE NOT NULL, payment_method VARCHAR(40) NOT NULL DEFAULT 'cash', transaction_reference VARCHAR(120) NULL, recorded_by BIGINT UNSIGNED NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(recorded_by) REFERENCES users(id), FOREIGN KEY(branch_id) REFERENCES branches(id), INDEX(expense_date));
CREATE TABLE notifications (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NULL, customer_id BIGINT UNSIGNED NULL, title VARCHAR(180) NOT NULL, body TEXT NOT NULL, read_at DATETIME NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE CASCADE, INDEX(user_id,read_at));
CREATE TABLE pharmacy_settings (setting_key VARCHAR(100) PRIMARY KEY, setting_value TEXT NOT NULL, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
INSERT IGNORE INTO pharmacy_settings(setting_key,setting_value) VALUES ('pharmacy_name','Mwangaza Pharmacy'),('currency','TZS'),('primary_color','#087967'),('accent_color','#eaf5f1'),('logo_url',''),('favicon_url',''),('hero_title','Your trusted neighbourhood pharmacy'),('hero_text','Quality medicines and friendly professional care.'),('contact_phone',''),('contact_email',''),('address',''),('map_link',''),('social_facebook',''),('social_instagram',''),('social_whatsapp','');
INSERT IGNORE INTO branches(name,location,address,phone,contact_email,finance_email,payment_instructions) SELECT setting_value,'','','','','','' FROM pharmacy_settings WHERE setting_key='pharmacy_name';

CREATE TABLE public_feedback (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, full_name VARCHAR(160) NOT NULL, email VARCHAR(190) NULL, branch_id BIGINT UNSIGNED NULL, rating TINYINT UNSIGNED NULL, message TEXT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(branch_id) REFERENCES branches(id) ON DELETE SET NULL, INDEX idx_public_feedback_created(created_at));
